<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>راستا — هر قدم، نزدیک‌تر به هدف</title><script>(()=>{const t=localStorage.getItem('rasta-theme')||'system';const dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.classList.toggle('dark',dark);document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.dataset.themePreference=t})()</script>@vite(['resources/css/app.css','resources/js/app.js'])</head><body><main class="gate-page page-enter" x-data="{saving:false}"><section class="gate-card"><a class="brand" href="/login"><span class="brand-symbol"><span></span><span></span><span></span></span><strong>راستا<small>هر قدم، نزدیک‌تر به هدف</small></strong></a><h1>شما کی هستید؟</h1><p class="muted">پروفایل خودتان را انتخاب کنید یا به تیم بپیوندید.</p><div class="profile-list">@foreach($members as $member)<form method="POST" action="/profiles">@csrf<input type="hidden" name="member_id" value="{{ $member->id }}"><button class="profile-choice"><span class="avatar">@if($member->avatar_url)<img src="{{ $member->avatar_url }}" alt="{{ $member->name }}">@else<span style="background:{{ $member->color }}">{{ collect(preg_split('/\s+/u',$member->name))->filter()->take(2)->map(fn($part)=>mb_substr($part,0,1))->implode('') }}</span>@endif</span><span>{{ $member->name }}<small>{{ $member->job_title }}</small></span></button></form>@endforeach</div><form method="POST" action="/profiles" @submit="saving=true">@csrf<h2>افزودن خودم</h2><label>نام و نام خانوادگی<input name="name" value="{{ old('name') }}" required maxlength="100"></label>@error('name')<small class="field-error">{{ $message }}</small>@enderror<label>عنوان شغلی<input name="job_title" value="{{ old('job_title') }}" required maxlength="100"></label>@error('job_title')<small class="field-error">{{ $message }}</small>@enderror<button class="button primary" 